 bg=[card("居鲁士圆柱", "<p>1879年在巴比伦出土。古列自称受马尔杜克之命，让被掳的民族带着神像回乡、修复神庙。这一<b class='k'>宗教宽容政策</b>与拉1章吻合；而圣经说是“耶和华激动古列的心”，并预言他的名字（赛44:28；45:1）。</p>", "🏺", "var(--gold)"),
     card("亚兰文：帝国的通用语", "<p>波斯帝国的公文使用“帝国亚兰文”。以斯拉记保存了原文书信，与象岛蒲草纸的格式相符（如“……的仆人……”的致词、档案查询程序）。</p>", "📨", "var(--blue)"),
     card("撒玛利亚人的“参与”", "<p>他们说“我们寻求你们的神，与你们一样”（4:2），但王下17:33 说他们“又惧怕耶和华，又事奉自己的神”。拒绝合作不是种族歧视，而是<b class='k'>拒绝混合的敬拜</b>。</p>", "🚫", "var(--red)"),
     card("文士的兴起", "<p>没有王、圣殿也不如从前，神的百姓越来越以<b class='k'>律法书</b>为中心。以斯拉是“文士”这一职分的典范——后来演变为新约时代的文士（虽然多已偏离）。</p>", "✍️", "var(--purple)")],
 cov=COV('<p>以斯拉记展示<b class="k">“约的更新”</b>：① 神信守应许（七十年）；② 恢复约的敬拜（祭坛、节期、圣殿）；③ 恢复约的律法（以斯拉）；④ 恢复约的圣洁（通婚问题，参申7:3-4）。但这一切都是<b class="k">“小日子”</b>（亚4:10）：没有约柜、没有荣光降临、没有大卫的王——百姓仍在等候更大的复兴。</p>') + V("拉3:11"),
